//! Everything the two firmware images share: the S2 data, the timing harness, and where the
//! result goes.
#![no_std]

use cortex_m::peripheral::{Peripherals, DWT};
use nalgebra::{SMatrix, SVector};

/// Scenario S2's model and first measurements, generated by `build.rs`.
pub mod s2 {
    include!(concat!(env!("OUT_DIR"), "/s2.rs"));
}

/// Cycles per predict + update step, written after the run for a debugger or probe to read
/// (for example `probe-rs read b32 <address of CYCLES_PER_STEP>`).
#[no_mangle]
pub static mut CYCLES_PER_STEP: u32 = 0;

/// The final state, kept so the filter work can't be optimized away.
#[no_mangle]
pub static mut FINAL_STATE: [f32; 4] = [0.0; 4];

/// Converts a row-major array to a matrix.
pub fn matrix<const R: usize, const C: usize>(rows: &[[f32; C]; R]) -> SMatrix<f32, R, C> {
    SMatrix::from_fn(|i, j| rows[i][j])
}

/// Returns measurement `k` as a vector.
pub fn measurement(k: usize) -> SVector<f32, 2> {
    SVector::<f32, 2>::from(s2::ZS[k])
}

/// Times `run`, which filters all `s2::STEPS` measurements and returns the final state, then
/// stores the results and halts.
pub fn time_and_halt(run: impl FnOnce() -> SVector<f32, 4>) -> ! {
    let mut cp = Peripherals::take().unwrap();
    cp.DCB.enable_trace();
    cp.DWT.enable_cycle_counter();

    let start = DWT::cycle_count();
    let state = run();
    let cycles = DWT::cycle_count().wrapping_sub(start);

    // SAFETY: single-threaded, and nothing else touches these.
    unsafe {
        core::ptr::write_volatile(&raw mut CYCLES_PER_STEP, cycles / s2::STEPS as u32);
        core::ptr::write_volatile(&raw mut FINAL_STATE, state.into());
    }
    loop {
        cortex_m::asm::bkpt();
    }
}
